// Minimal C-like sketch (conceptual)
typedef struct io_req { uint64_t lba; uint32_t len; int id; struct io_req *next; } io_req;
typedef struct { io_req *head, *tail; } ring_t;
static inline void io_enqueue(ring_t *q, io_req *r) { r->next = NULL; /* CAS-based tail append */ }
static inline io_req* io_dequeue(ring_t *q) { /* pop head */ return NULL; }
static inline int can_merge(io_req *a, io_req *b) { return a->lba + a->len == b->lba; }
static inline io_req* merge_adjacent(io_req *a, io_req *b) {
  if (!can_merge(a,b)) return NULL; a->len += b->len; return a;
}
